  "tags": [
    "example",
    "first-party",
    "prototype",
    "web",
    "web-worker",
    "worker",
    "simulation",
    "particles",
    "sharedarraybuffer",
    "offscreencanvas",
    "powered-preview",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "scenario": "design",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Build a real-time {{subject}} visualizer whose heavy compute runs in a Web Worker (sharing memory via SharedArrayBuffer when available), rendered to canvas at 60fps as a single self-contained index.html.",
        "zh-CN": "构建一个实时的{{subject}}可视化器，将繁重计算放到 Web Worker 中运行（可用时通过 SharedArrayBuffer 共享内存），作为单个自包含的 index.html 以 60fps 渲染到画布。"
      }
    },
    "inputs": [
      {
        "name": "subject",
        "label": "What should it simulate?",
        "type": "text",
        "required": false,
        "default": "a 12,000-body swirling particle field",
        "placeholder": "e.g. an N-body galaxy, a Mandelbrot zoom, reaction-diffusion"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      }
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
